#!/usr/bin/env python3
"""Extend the normal-batch audit to at least 600 attempted batches.

New intervals do not overlap prior intervals on the same chain. Results are
checkpointed after every batch so the experiment can resume safely.
"""

from __future__ import annotations

# --- github publish layout (auto-generated by sync_github_publish.py) ---
import sys
from pathlib import Path as _Path
_GITHUB_ROOT = _Path(__file__).resolve().parents[1]
_BG = _GITHUB_ROOT / "BoundaryGuard"
_EXP = _GITHUB_ROOT / "exp"
for _p in (_BG, _EXP):
    _s = str(_p)
    if _s not in sys.path:
        sys.path.insert(0, _s)
DATA = _GITHUB_ROOT.joinpath("data")
EXP = _EXP
ROOT = _GITHUB_ROOT
# --- end header ---

import json
import math
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

import boundaryguard_scale_gate as base


EXTRA_PER_CHAIN = 152
EXTRA = base.DATA / "boundaryguard_scale_normal_extension_600.jsonl"
COMBINED = base.DATA / "boundaryguard_scale_normal_600.jsonl"
SUMMARY = base.DATA / "boundaryguard_scale_normal_600_summary.json"
LOCK = threading.Lock()


def overlaps(start: int, occupied: list[tuple[int, int]]) -> bool:
    end = start + base.BATCH_WIDTH - 1
    return any(not (end < left or start > right) for left, right in occupied)


def choose_intervals(rows: list[dict], occupied: list[tuple[int, int]], count: int) -> list[tuple[int, int]]:
    lo = rows[0]["origin_block_height"] + 1
    hi = rows[-1]["origin_block_height"] - base.BATCH_WIDTH - 1
    selected = []
    # Dense deterministic candidates make selection independent of RPC outcomes.
    for index in range(1, 20001):
        start = round(lo + index * (hi - lo) / 20002)
        if not overlaps(start, occupied + selected):
            selected.append((start, start + base.BATCH_WIDTH - 1))
            if len(selected) == count:
                return selected
    raise RuntimeError(f"could only select {len(selected)} non-overlapping intervals")


def append(record: dict) -> None:
    with LOCK:
        with EXTRA.open("a") as handle:
            handle.write(json.dumps(record, sort_keys=True) + "\n")
            handle.flush()


def run_chain(chain: str, rows: list[dict], intervals: list[tuple[int, int]], done: set[tuple]) -> None:
    cfg = base.CONFIG[chain]
    mailbox = base.normalize(rows[0]["origin_mailbox"])
    for index, (start, end) in enumerate(intervals):
        if (chain, start, end) in done:
            continue
        wall_started = time.perf_counter()
        before = base.read_nonce(cfg["boundary_url"], mailbox, start - 1)
        after = base.read_nonce(cfg["boundary_url"], mailbox, end)
        primary = base.rpc_retry(
            cfg["primary_url"], "eth_getLogs",
            [{"fromBlock": hex(start), "toBlock": hex(end), "address": mailbox,
              "topics": [base.DISPATCH_TOPIC]}],
        )
        logs = primary.pop("result", None)
        returned = len(logs) if isinstance(logs, list) else None
        expected = None if before["value"] is None or after["value"] is None else after["value"] - before["value"]
        valid = expected is not None and returned is not None
        record = {
            "provenance": "live_natural_observation", "ts": time.time(), "chain": chain,
            "batch_index": 151 + index, "start": start, "end": end, "width": base.BATCH_WIDTH,
            "mailbox": mailbox, "primary": cfg["primary_name"], "boundary": cfg["boundary_name"],
            "repair": cfg["repair_name"], "nonce_before": before["value"], "nonce_after": after["value"],
            "expected_dispatches": expected, "returned_dispatches": returned, "valid": valid,
            "alarm": valid and expected != returned, "wall_ms": round((time.perf_counter()-wall_started)*1000, 3),
            "primary_outcome": primary["outcome"], "primary_latency_ms": primary["latency_ms"],
            "primary_attempts": primary["attempts"], "primary_history": primary["attempt_history"],
            "boundary_before_outcome": before["outcome"], "boundary_before_attempts": before["attempts"],
            "boundary_before_latency_ms": before["latency_ms"], "boundary_after_outcome": after["outcome"],
            "boundary_after_attempts": after["attempts"], "boundary_after_latency_ms": after["latency_ms"],
        }
        append(record)
        print(chain, index + 1, "/", len(intervals), "valid", valid, "alarm", record["alarm"],
              "attempts", (before["attempts"], after["attempts"], primary["attempts"]), flush=True)
        time.sleep(0.15)


def main() -> None:
    original = [json.loads(line) for line in (base.ROOT / "data/boundaryguard_scale_normal_combined.jsonl").open()]
    extension = [json.loads(line) for line in EXTRA.open()] if EXTRA.exists() else []
    done = {(row["chain"], row["start"], row["end"]) for row in extension}
    grouped = base.load_chains()
    intervals = {}
    for chain, rows in grouped.items():
        occupied = [(r["start"], r["end"]) for r in original if r["chain"] == chain]
        intervals[chain] = choose_intervals(rows, occupied, EXTRA_PER_CHAIN)
    with ThreadPoolExecutor(max_workers=2) as pool:
        futures = [pool.submit(run_chain, chain, rows, intervals[chain], done) for chain, rows in grouped.items()]
        for future in futures:
            future.result()
    extension = [json.loads(line) for line in EXTRA.open()]
    combined = sorted(original + extension, key=lambda r: (r["chain"], r["start"]))
    with COMBINED.open("w") as handle:
        for row in combined:
            handle.write(json.dumps(row, sort_keys=True) + "\n")
    summary = base.summarize(combined)
    valid = summary["overall"]["valid_batches"]
    alarms = summary["overall"]["alarms"]
    if alarms == 0:
        summary["overall"]["zero_alarm_exact_one_sided_95pct_upper"] = 1 - math.pow(0.05, 1/valid)
    SUMMARY.write_text(json.dumps(summary, indent=2, sort_keys=True) + "\n")
    print(json.dumps(summary, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
